insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"dermaquest","slug":"3d-stem-cell-face-eye-cream","title_zh_hk":"3D\u5e79\u7d30\u80de\u773c\u9762\u971c","title_zh_cn":"3D\u5e72\u7ec6\u80de\u773c\u9762\u971c","title_en":"3D Stem Cell Face & Eye Cream","description_zh_hk":"<p>\u9069\u5408\u6240\u6709\u808c\u819a</p>\n<p>\u900f\u904e\u5c08\u5229\u91ab\u5b78\u5e79\u7d30\u80de\u57f9\u80b2\u6280\u8853\u800c\u7814\u767c\uff0c\u7d42\u6975\u89e3\u51b3\u8001\u5316\u808c\u819a\u554f\u984c\uff0c\u540c\u6b65\u5b8c\u6210\u63d0\u5347\u3001\u518d\u751f\u53ca\u4eae\u767d3\u5927\u7f8e\u5bb9\u6548\u679c\u3002\u4ee5\u6d77\u6d0b\u751f\u7269\u79d1\u6280\u3001\u91ab\u5b78\u5e79\u7d30\u80de\u53ca\u86cb\u767d\u80bd\u7b49\u914d\u65b9\uff0c\u523a\u6fc0\u9aa8\u81a0\u539f\u7522\u751f\u7dca\u7e2e\u4f5c\u7528\uff0c\u9054\u5230\u5ab2\u7f8e\u6fc0\u5149\u7f8e\u5bb9\u7684\u63d0\u5347\u7dca\u7dfb\u7642\u6548\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u4eae\u767d\u3001\u4fee\u5fa9\u3001\u6297\u8870\u8001</p>\n<p>\u2013 \u6e1b\u6de1\u5e7c\u7d0b\u53ca\u76ba\u7d0b</p>\n<p>\u2013 \u6539\u5584\u808c\u8089\u9b06\u5f1b\uff0c\u63d0\u5347\u9762\u90e8\u8f2a\u5ed3</p>\n<p>\u2013 \u6536\u7dca\u808c\u819a\u7d44\u7e54\uff0c\u5f9e\u6839\u6e90\u6539\u5584\u76ba\u7d0b\u53ca\u808c\u819a\u7c97\u7cd9\u7b49\u554f\u984c</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u706b\u7d68\u8349\u5e79\u7d30\u80de</p>\n<p>\u2013 \u6894\u5b50\u82b1\u5e79\u7d30\u80de</p>\n<p>\u2013 \u6d77\u8334\u9999\u5e79\u7d30\u80de</p>","description_zh_cn":"<p>\u9002\u5408\u6240\u6709\u808c\u80a4</p>\n<p>\u900f\u8fc7\u4e13\u5229\u533b\u5b66\u5e72\u7ec6\u80de\u57f9\u80b2\u6280\u672f\u800c\u7814\u53d1\uff0c\u7ec8\u6781\u89e3\u51b3\u8001\u5316\u808c\u80a4\u95ee\u9898\uff0c\u540c\u6b65\u5b8c\u6210\u63d0\u5347\u3001\u518d\u751f\u53ca\u4eae\u767d3\u5927\u7f8e\u5bb9\u6548\u679c\u3002\u4ee5\u6d77\u6d0b\u751f\u7269\u79d1\u6280\u3001\u533b\u5b66\u5e72\u7ec6\u80de\u53ca\u86cb\u767d\u80bd\u7b49\u914d\u65b9\uff0c\u523a\u6fc0\u9aa8\u80f6\u539f\u4ea7\u751f\u7d27\u7f29\u4f5c\u7528\uff0c\u8fbe\u5230\u5ab2\u7f8e\u6fc0\u5149\u7f8e\u5bb9\u7684\u63d0\u5347\u7d27\u81f4\u7597\u6548\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u4eae\u767d\u3001\u4fee\u590d\u3001\u6297\u8870\u8001</p>\n<p>\u2013 \u51cf\u6de1\u5e7c\u7eb9\u53ca\u76b1\u7eb9</p>\n<p>\u2013 \u6539\u5584\u808c\u8089\u677e\u5f1b\uff0c\u63d0\u5347\u9762\u90e8\u8f6e\u5ed3</p>\n<p>\u2013 \u6536\u7d27\u808c\u80a4\u7ec4\u7ec7\uff0c\u4ece\u6839\u6e90\u6539\u5584\u76b1\u7eb9\u53ca\u808c\u80a4\u7c97\u7cd9\u7b49\u95ee\u9898</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u706b\u7ed2\u8349\u5e72\u7ec6\u80de</p>\n<p>\u2013 \u6800\u5b50\u82b1\u5e72\u7ec6\u80de</p>\n<p>\u2013 \u6d77\u8334\u9999\u5e72\u7ec6\u80de</p>","description_en":"<p>Suitable for all skin types</p>\n<p>Patented medical stem-cell cultivation for ageing skin: lift, regenerate and brighten in one cream, with a firming effect comparable to laser lifting.</p>\n<p>Key benefits</p>\n<p>\u2013 Brighten, repair and anti-age</p>\n<p>\u2013 Soften fine lines and wrinkles</p>\n<p>\u2013 Improve slackness and lift facial contours</p>\n<p>\u2013 Tighten tissue and help roughness at the source</p>\n<p>Key ingredients</p>\n<p>\u2013 Edelweiss stem cells</p>\n<p>\u2013 Gardenia stem cells</p>\n<p>\u2013 Sea fennel stem cells</p>","price_hkd":2200,"stock":20,"image_paths":["/images/products/prod-3@2x.jpg"],"sort":227}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;